rollback.sql:
DO $report_content_rollback$
BEGIN
    LOCK TABLE clinlims.report_document, clinlims.patient_report_release IN ACCESS EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM clinlims.report_document WHERE group_rules_json IS NOT NULL OR group_rules_sha256 IS NOT NULL)
       OR EXISTS (SELECT 1 FROM clinlims.patient_report_release WHERE frozen_content_json IS NOT NULL OR frozen_content_sha256 IS NOT NULL OR frozen_at IS NOT NULL OR issuer_name_printed IS NOT NULL) THEN
        RAISE EXCEPTION 'Frozen report evidence exists; retain it and use a forward migration';
    END IF;
    ALTER TABLE clinlims.report_document DROP CONSTRAINT ck_report_document_rules;
    ALTER TABLE clinlims.report_document DROP COLUMN group_rules_json, DROP COLUMN group_rules_sha256;
    ALTER TABLE clinlims.patient_report_release DROP CONSTRAINT ck_report_release_frozen_content;
    ALTER TABLE clinlims.patient_report_release DROP COLUMN frozen_content_json, DROP COLUMN frozen_content_sha256, DROP COLUMN frozen_at, DROP COLUMN issuer_name_printed;
END;
$report_content_rollback$;
